  },
  fontWeight: {
    type: "number",
    default: 500,
    min: 300,
    max: 900,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  density: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 2,
    step: 0.1,
    description: "Hatch density",
    hiddenFromList: false,
  },
